def distance(graph, start, end):
    from collections import deque
    q=deque([(start,0)]); seen={start}
    while q:
        n,d=q.popleft()
        if n==end: return d
        for v in graph.get(n,[]):
            if v not in seen: seen.add(v); q.append((v,d+1))
    return None

